xml.Script:
        Colors[0] := 'FF0000'; // Red
        Colors[1] := '008000'; // Green
        Colors[2] := 'C8C8C8'; // Light Gray
        Colors[3] := '00FF00'; // Light Green
        Colors[4] := 'FF6000'; // Orange
        Colors[5] := '0064FF'; // Sky Blue
        Colors[6] := 'FFFF00'; // Yellow
        Colors[7] := 'FF64FF'; // Pink

        R := 0.6;
        H := R * 0.7;

        NA := 9;
        WD := R * 0.09;
        for i := 0 to NA - 2 do
            D[i] := WD * i - WD * (NA - 2) / 2;

        N := 6;
        A := 2*Pi / N;
        for i := 0 to N - 1 do begin
            x[i] := R * cos(A * i);
            y[i] := R * sin(A * i);
        end;

        function FromTo(iFrom, iTo);
        begin
            Result := IntToStr(iFrom);
            for i := iFrom + 1 to iTo do
                Result := Result + ';' + IntToStr(i);
            for i := iFrom - 1 downto iTo do
                Result := Result + ';' + IntToStr(i);
        end;

Macro.Script:
i1 := i mod N;
i2 := (i + 1) mod N;
Inc(i);
